(()=>{
const $=id=>document.getElementById(id),key='sudoku-saisons-v1';let s=null,selected=-1,noteMode=false,paused=false,autoPaused=false,sound=false,audio=null,saveFailed=false,lastTick=performance.now();
let inSetup=true,chosenTheme='spring',modalWasPaused=false,decorGrace=0;
const blank=()=>({level:'easy',theme:'spring',delay:90,motion:matchMedia('(prefers-reduced-motion: reduce)').matches,best:0});
try{let raw=JSON.parse(localStorage.getItem(key));if(raw&&Array.isArray(raw.puzzle)&&raw.puzzle.length===81&&raw.solution?.length===81&&raw.values?.length===81&&raw.notes?.length===81&&raw.puzzle.every((v,i)=>Number.isInteger(v)&&v>=0&&v<=9&&(!v||v===raw.solution[i]))&&raw.values.every((v,i)=>Number.isInteger(v)&&v>=0&&v<=9&&(!v||v===raw.solution[i]))&&Sudoku.countSolutions(raw.solution)===1){s=raw;s.notes=s.notes.map(a=>Array.isArray(a)?a.filter(n=>Number.isInteger(n)&&n>=1&&n<=9):[]);s.hinted=Array.isArray(s.hinted)?s.hinted.filter(n=>Number.isInteger(n)&&n>=0&&n<81):[];for(let k of ['score','elapsed','errors','best','combo','streak'])s[k]=Math.max(0,Number(s[k])||0);s.hints=Number.isInteger(s.hints)?Math.max(0,Math.min(3,s.hints)):3;s.level=['easy','medium','hard'].includes(s.level)?s.level:'easy';s.theme=['spring','summer','autumn','winter'].includes(s.theme)?s.theme:'spring';s.delay=[0,90,120,180].includes(s.delay)?s.delay:90;s.remaining=Math.max(0,Number(s.remaining)||0)}}catch(e){}
function save(){if(!s)return;try{localStorage.setItem(key,JSON.stringify(s))}catch(e){if(!saveFailed){saveFailed=true;$('message').textContent='Sauvegarde indisponible dans ce navigateur. La partie reste jouable.';document.querySelector('footer span').textContent='Sauvegarde indisponible sur cet appareil'}}}
function revealPlay(){document.body.classList.add('is-playing');requestAnimationFrame(()=>{World.refresh();let panel=document.querySelector('.boardpanel');if(panel&&innerWidth<701){let bounds=panel.getBoundingClientRect(),height=window.visualViewport?.height||innerHeight,usable=height-165;let top=window.scrollY+bounds.top-Math.max(12,(usable-bounds.height)/2);window.scrollTo({top:Math.max(0,top),behavior:'instant'})}else document.getElementById('play').scrollIntoView({block:'start',behavior:'instant'})})}
function newGame(level='easy'){let pref={...(s||blank()),theme:chosenTheme},g=Sudoku.generate(level);s={...blank(),theme:pref.theme,delay:pref.delay,motion:pref.motion,best:pref.best||0,level,...g,values:g.puzzle.slice(),notes:Array.from({length:81},()=>[]),hinted:[],score:0,combo:0,streak:0,remaining:pref.delay,elapsed:0,errors:0,hints:3,won:false};selected=s.values.indexOf(0);inSetup=false;$('setup').hidden=true;$('play').hidden=false;World.reset();paused=false;noteMode=false;lastTick=performance.now();applyPreferences();render();World.pause(false);World.refresh();revealPlay();save();$('message').textContent='Le gardien est prêt. Enfin, à peu près.'}
function say(text,type='correct',i=selected){$('message').textContent=text;$('sceneToast').textContent=text;World.event(type,i,s.combo);if(sound)tone(type)}
function tone(type){try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();let now=audio.currentTime,seq=type==='error'?[160]:type==='hint'?[440,660]:type==='combo'?[523,659,784]:[523,659];seq.forEach((hz,i)=>{let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=hz;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(0,now+i*.09);g.gain.linearRampToValueAtTime(.045,now+i*.09+.01);g.gain.exponentialRampToValueAtTime(.001,now+i*.09+.28);o.start(now+i*.09);o.stop(now+i*.09+.3)})}catch(e){sound=false}}
function applyPreferences(){document.body.dataset.theme=s.theme;document.body.classList.toggle('reduced',s.motion);World.theme(s.theme);World.motion(s.motion);$('difficulty').value=s.level;$('delay').value=s.delay;$('motion').checked=s.motion;$('difficultyLabel').textContent={easy:'Promenade',medium:'Randonnée',hard:'Expédition'}[s.level]}
const cells=[];for(let i=0;i<81;i++){let b=document.createElement('button');b.className='cell';b.onclick=()=>{if(inSetup||!s||paused)return;selected=i;render()};b.dataset.index=i;cells.push(b);$('board').append(b)}for(let n=1;n<=9;n++){let b=document.createElement('button');b.textContent=n;b.setAttribute('aria-label','Entrer le chiffre '+n);b.onclick=()=>enter(n);$('numbers').append(b)}
function format(t){t=Math.floor(t);return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')}
function metrics(){if(!s)return;$('score').textContent=s.score.toLocaleString('fr-FR');$('combo').textContent='× '+Math.min(s.combo,10);$('best').textContent=s.best;$('clock').textContent=format(s.elapsed);$('comboLeft').textContent=s.delay===0?'∞':format(s.remaining);$('comboBar').style.width=(s.delay?Math.max(0,s.remaining/s.delay)*100:100)+'%';$('comboText').textContent=s.combo?`${s.streak} bonne${s.streak>1?'s':''} réponse${s.streak>1?'s':''} · multiplicateur ×${Math.min(s.combo,10)}`:s.delay?`${s.delay} secondes pour enchaîner. Respirez.`:'Mode zen · prenez tout votre temps.';let empty=s.puzzle.filter(x=>!x).length,filled=s.values.filter((v,i)=>v&&!s.puzzle[i]).length,p=Math.round(filled/empty*100);$('progress').textContent=p+'%';$('progressBar').style.width=p+'%';$('progressLabel').textContent=`${filled} / ${empty} découvertes dans votre escapade`;$('hintCount').textContent=s.hints;$('hint').disabled=s.hints===0||s.won;$('pauseOverlay').hidden=!paused;$('pauseIcon').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Reprendre la partie':'Mettre en pause');}
function render(){if(!s)return;let r=Math.floor(selected/9),c=selected%9;cells.forEach((b,i)=>{let rr=Math.floor(i/9),cc=i%9,given=!!s.puzzle[i],value=s.values[i],peer=selected>=0&&(rr===r||cc===c||(Math.floor(rr/3)===Math.floor(r/3)&&Math.floor(cc/3)===Math.floor(c/3)));b.className='cell'+(given?' given':value?' found':'')+(cc===2||cc===5?' block-right':'')+(rr===2||rr===5?' block-bottom':'')+(peer?' peer':'')+(value&&selected>=0&&value===s.values[selected]?' same':'')+(selected===i?' selected':'')+(s.hinted.includes(i)?' hinted':'');b.replaceChildren();if(value)b.textContent=value;else if(s.notes[i].length){let box=document.createElement('span');box.className='miniNotes';for(let n=1;n<=9;n++){let el=document.createElement('span');el.textContent=s.notes[i].includes(n)?n:'';box.append(el)}b.append(box)}b.setAttribute('aria-label',`Ligne ${rr+1}, colonne ${cc+1}, ${value?value:'vide'}${given?', chiffre initial':''}${s.notes[i].length?', notes '+s.notes[i].join(', '):''}`);b.setAttribute('aria-pressed',i===selected)});$('notes').classList.toggle('active',noteMode);$('notes').setAttribute('aria-pressed',noteMode);[...$('numbers').children].forEach((b,i)=>b.classList.toggle('done',s.values.filter(v=>v===i+1).length===9));metrics();World.update(s,selected)}
function clearPeers(i,n){let r=Math.floor(i/9),c=i%9;s.notes.forEach((a,j)=>{let rr=Math.floor(j/9),cc=j%9;if(rr===r||cc===c||(Math.floor(rr/3)===Math.floor(r/3)&&Math.floor(cc/3)===Math.floor(c/3)))s.notes[j]=a.filter(x=>x!==n)})}
function enter(n,hint=false){if(inSetup||!s||paused||s.won)return;if(selected<0){$('message').textContent='Choisissez d’abord une case.';return}if(s.values[selected]){$('message').textContent='Cette case est déjà résolue.';return}if(noteMode&&!hint){let a=s.notes[selected];s.notes[selected]=a.includes(n)?a.filter(x=>x!==n):[...a,n].sort();render();save();return}if(n!==s.solution[selected]){s.errors++;s.combo=0;s.streak=0;s.remaining=s.delay;say('Une fausse piste. Prenez votre temps, puis réessayez.','error');render();cells[selected].classList.add('error');save();return}s.values[selected]=n;s.notes[selected]=[];clearPeers(selected,n);if(hint){s.hinted.push(selected);s.hints--;s.combo=0;s.streak=0;s.remaining=s.delay;say('Un rayon de lumière : la case a été révélée.','hint')}else{s.combo++;s.streak++;s.best=Math.max(s.best,s.streak);s.remaining=s.delay;let points=100*Math.min(s.combo,10);s.score+=points;say(s.combo>=3?`Combo ×${Math.min(s.combo,10)} ! +${points} points.`:'Une nouvelle découverte. +'+points+' points.',s.combo>=3?'combo':'correct')}
if(s.values.every(Boolean)){s.won=true;say('Grille complète ! Le gardien vous décerne son respect.','win');$('winSummary').textContent=`${s.score.toLocaleString('fr-FR')} points en ${format(s.elapsed)} · ${s.errors} erreur${s.errors>1?'s':''} · meilleur enchaînement : ${s.best}.`;$('winDialog').showModal()}render();save()}
$('notes').onclick=()=>{if(inSetup||!s||paused||s.won)return;noteMode=!noteMode;render()};$('erase').onclick=()=>{if(inSetup||!s||paused||selected<0)return;if(s.values[selected]){$('message').textContent='Les bonnes réponses restent acquises. Vous pouvez effacer vos notes.';return}s.notes[selected]=[];render();save()};$('hint').onclick=()=>{if(inSetup||!s||paused||s.won||!s.hints)return;if(selected<0||s.values[selected])selected=s.values.indexOf(0);if(selected<0)return;enter(s.solution[selected],true)};
function pause(value){paused=value;World.pause(value);lastTick=performance.now();metrics()}$('pause').onclick=()=>pause(!paused);$('resume').onclick=()=>pause(false);
$('settings').onclick=()=>{if(!s){$('delay').value=preferences.delay;$('motion').checked=preferences.motion}modalWasPaused=paused;$('settingsDialog').showModal();pause(true)};$('settingsDialog').addEventListener('close',()=>pause(modalWasPaused));$('delay').onchange=e=>{preferences.delay=Number(e.target.value);if(s){s.delay=preferences.delay;s.remaining=s.delay;metrics();save()}};$('motion').onchange=e=>{preferences.motion=e.target.checked;if(s)s.motion=preferences.motion;document.body.classList.toggle('reduced',preferences.motion);World.motion(preferences.motion);save()};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♪ Son activé':'♪ Son désactivé';$('sound').setAttribute('aria-label',sound?'Désactiver les sons':'Activer les sons');if(sound)tone('correct')};
let preferences=s?{delay:s.delay,motion:s.motion}:blank();
function selectMap(theme){chosenTheme=theme;document.body.dataset.theme=theme;World.theme(theme);document.querySelectorAll('[data-theme]').forEach(b=>{let on=b.dataset.theme===theme;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);b.querySelector('.chosen').textContent=on?'Sélectionnée ✓':'Choisir cette map ↗'})}
function showSetup(){document.body.classList.remove('is-playing');inSetup=true;pause(true);$('setup').hidden=false;$('play').hidden=true;$('continue').hidden=!s;selectMap(s?.theme||chosenTheme);$('difficulty').value=s?.level||'easy';$('start').focus()}
document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>selectMap(b.dataset.theme));
$('start').onclick=()=>{if(s){s.delay=preferences.delay;s.motion=preferences.motion}else{s={...blank(),...preferences}}newGame($('difficulty').value)};
$('continue').onclick=()=>{if(!s?.puzzle)return;inSetup=false;$('setup').hidden=true;$('play').hidden=false;applyPreferences();pause(false);render();World.refresh();revealPlay()};
$('new').onclick=()=>{modalWasPaused=paused;$('newDialog').showModal();pause(true)};
$('newDialog').addEventListener('close',()=>{if($('newDialog').returnValue==='confirm')showSetup();else pause(modalWasPaused)});
window.addEventListener('decorinteraction',()=>{if(!inSetup&&!paused)decorGrace=3});
window.addEventListener('worldselect',e=>{if(!inSetup&&s&&!paused){selected=e.detail;render()}});
document.addEventListener('keydown',e=>{if(inSetup||!s||document.querySelector('dialog[open]')||e.target.closest('dialog,select,input'))return;if(e.key===' '){e.preventDefault();pause(!paused);return}if(paused)return;if(/^[1-9]$/.test(e.key)){e.preventDefault();enter(Number(e.key))}else if(e.key.toLowerCase()==='n'){$('notes').click()}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();$('erase').click()}else if(e.key.startsWith('Arrow')){e.preventDefault();if(selected<0)selected=0;else{let r=Math.floor(selected/9),c=selected%9;if(e.key==='ArrowLeft')c=Math.max(0,c-1);if(e.key==='ArrowRight')c=Math.min(8,c+1);if(e.key==='ArrowUp')r=Math.max(0,r-1);if(e.key==='ArrowDown')r=Math.min(8,r+1);selected=r*9+c}render();cells[selected].focus()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){autoPaused=!paused;pause(true);save()}else if(autoPaused){autoPaused=false;pause(false)}});
setInterval(()=>{let now=performance.now(),dt=Math.min((now-lastTick)/1000,2);lastTick=now;if(inSetup||!s||paused||s.won||document.hidden)return;s.elapsed+=dt;let comboDt=decorGrace>0?Math.max(0,dt-decorGrace):dt;decorGrace=Math.max(0,decorGrace-dt);if(s.combo&&s.delay){s.remaining=Math.max(0,s.remaining-comboDt);if(!s.remaining){s.combo=0;s.streak=0;$('message').textContent='Le combo se repose. La prochaine réponse démarre une nouvelle série.';$('sceneToast').textContent='Prenez votre temps. Le gardien patiente avec vous.'}}metrics()},250);setInterval(save,3000);window.addEventListener('pagehide',save);
if(s){selected=s.values.indexOf(0);applyPreferences();render()}showSetup();
})();
